          { personIds, from: from || null },
          { headers },
        ),
      );
      if (this.session.sheet() !== sheet) return;
      this.selectedPeople.set(new Set());
      await this.reload(sheet);
      if (this.session.sheet() !== sheet) return;
      this.bulkRetired.set(result.retired);
